task.vi:
Tại sao lớp Person sau đây cần có một destructor? Hãy viết bổ sung destructor đó vào lớp:

class Person
{
public:
  Person()
  {
    numberOfChildren = 0;
    children = new string[20];
  }

  void addAChild(string name)
  {
    children[numberOfChildren++] = name;
  }

  string* getChildren()
  {
    return children;
  }

  int getNumberOfChildren()
  {
    return numberOfChildren;
  }

private:
  string* children;
  int numberOfChildren;
};

