#include <iostream>
#include <string>

class Course {
public:
    Course(const std::string& courseName, int capacity) {
        this->numberOfStudents = 0;
        this->courseName = courseName;
        this->capacity = capacity;
        this->students = new std::string[capacity];
    }

    ~Course() {
        delete[] students;
    }

    std::string getCourseName() const {
        return courseName;
    }

    void addStudent(const std::string& name) {
        if (numberOfStudents < capacity) {
            students[numberOfStudents++] = name;
        }
    }

    void dropStudent(const std::string& name) {
        for (int i = 0; i < numberOfStudents; ++i) {
            if (students[i] == name) {
                for (int j = i; j < numberOfStudents - 1; ++j) {
                    students[j] = students[j + 1];
                }
                --numberOfStudents;
                return;
            }
        }
    }

    std::string* getStudents() const {
        return students;
    }

    int getNumberOfStudents() const {
        return numberOfStudents;
    }

private:
    std::string courseName;
    std::string* students;
    int numberOfStudents;
    int capacity;
};

int main() {
    Course course1("Data Structures", 10);
    Course course2("Database Systems", 15);

    course1.addStudent("Peter Jones");
    course1.addStudent("Brian Smith");
    course1.addStudent("Anne Kennedy");

    course2.addStudent("Peter Jones");
    course2.addStudent("Steve Smith");

    std::cout << "Number of students in course1: " << course1.getNumberOfStudents() << "\n";
    std::string* s1 = course1.getStudents();
    for (int i = 0; i < course1.getNumberOfStudents(); ++i) {
        std::cout << s1[i] << ", ";
    }

    std::cout << "\nNumber of students in course2: " << course2.getNumberOfStudents() << "\n";
    std::string* s2 = course2.getStudents();
    for (int i = 0; i < course2.getNumberOfStudents(); ++i) {
        std::cout << s2[i] << ", ";
    }
    std::cout << "\n";

    return 0;
}

#include <iostream>

class Circle {
public:
    Circle(double radius) {
        this->radius = radius;
    }

    // Copy constructor demonstrating deep value semantics
    Circle(const Circle& c) {
        this->radius = c.radius;
    }

    void setRadius(double radius) {
        this->radius = radius;
    }

    double getRadius() const {
        return radius;
    }

private:
    double radius;
};

int main() {
    Circle circle1(5.0);
    Circle circle2(circle1); // Invokes copy constructor

    std::cout << "After creating circle2 from circle1:\n";
    std::cout << "  circle1 radius = " << circle1.getRadius() << "\n";
    std::cout << "  circle2 radius = " << circle2.getRadius() << "\n";

    circle1.setRadius(10.5);
    circle2.setRadius(20.5);

    std::cout << "After modifying circle1 and circle2:\n";
    std::cout << "  circle1 radius = " << circle1.getRadius() << "\n";
    std::cout << "  circle2 radius = " << circle2.getRadius() << "\n";

    return 0;
}
